cd /code && python - <<'PY'
import nbformat,re
nb=nbformat.read('../results/FGBR_OC_executed.ipynb', as_version=4)
texts=[]
for c in nb.cells:
    if c.cell_type=='code':
        for o in c.get('outputs',[]):
            if o.output_type=='stream':
                texts.append(o.text)
text=''.join(texts)
print(text)
print('--- matches ---')
for m in re.finditer(r'c = 1.0.*?maxR2 =\s*([0-9.\-]+).*?minRMSE =\s*([0-9.\-]+)', text, re.S):
    print(m.group(1), m.group(2))
PY
